<script module lang="ts">
	import { DEFAULT_MASCOT, MASCOTS, type Mascot as MascotKey } from '../mascots';

	export type Mood = 'feliz' | 'triste';

	/** Clave válida del catálogo; cualquier otra cosa pinta la puerta (`sala`). */
	export function mascotKey(kind: string): MascotKey {
		return (MASCOTS as readonly string[]).includes(kind) ? (kind as MascotKey) : DEFAULT_MASCOT;
	}

	/**
	 * Onde vai a cara de cada instalación (x, y, escala en 100×100). Os símbolos `d-*` son neutros;
	 * a cara pona cada <Mascot> encima, só cando se ve grande.
	 */
	export const MASCOT_FACE: Record<MascotKey, readonly [number, number, number]> = {
		padel: [50, 70.2, 0.811],
		tenis: [50, 68.5, 0.874],
		squash: [50, 75, 0.74],
		badminton: [50, 70, 0.819],
		pingpong: [50, 61.2, 0.836],
		futbol: [50, 68.5, 0.874],
		basket: [50, 71, 0.78],
		volei: [50, 69.3, 0.842],
		balonmano: [50, 68.5, 0.874],
		rugby: [50, 69.7, 0.827],
		natacion: [50, 68.5, 0.762],
		fronton: [50, 21, 0.85],
		ximnasio: [50, 21, 0.82],
		atletismo: [50, 57.3, 0.739],
		escalada: [50, 23, 0.85],
		bolos: [50, 52, 0.62],
		ciclismo: [58.6, 70.4, 0.778],
		patinaxe: [50, 69.6, 0.829],
		golf: [45.8, 61.3, 0.742],
		piragua: [58.6, 70.4, 0.799],
		sala: [50, 22, 0.66]
	};

	// La hoja de símbolos se pinta una sola vez (en +layout.svelte) con {@render mascotSymbols()}.
	export { mascotSymbols };
</script>

<script lang="ts">
	let {
		kind,
		mood = 'feliz',
		size = 48,
		animated = true,
		color,
		face = size >= 48
	}: {
		kind: string;
		mood?: Mood;
		size?: number;
		animated?: boolean;
		/** Color de la puerta (`sala`) cuando el tipo no elige personaje. */
		color?: string;
		/** Cara enriba do debuxo: por defecto só a 48 px ou máis (a 28 px vese mellor neutro). */
		face?: boolean;
	} = $props();

	const key = $derived(mascotKey(kind));
	const spot = $derived(MASCOT_FACE[key]);
</script>

