<svg
	class="mascot"
	class:triste={mood === 'triste'}
	class:animado={animated}
	width={size}
	height={size}
	viewBox="0 0 100 100"
	aria-hidden="true"
	focusable="false"
	style:--m-color={color}
>
	<use href="#d-{key}" width="100" height="100" />
	{#if face}
		<g class="face" transform="translate({spot[0]} {spot[1]}) scale({spot[2]})"><use href="#F" /></g>
	{/if}
</svg>

<style>
	.mascot-symbols {
		position: absolute;
		width: 0;
		height: 0;
		overflow: hidden;
	}

	/* Humor y parpadeo: estilos en línea en los símbolos que leen variables heredadas por los <use> */
	.mascot.triste {
		--m-rir: none;
		--m-triste: inline;
	}

	.mascot {
		flex: none;
		overflow: visible;
		transform-origin: 50% 100%;
	}

	@media (prefers-reduced-motion: no-preference) {
		.mascot.animado {
			--m-blink: m-blink 4.2s infinite;
			animation: m-bob 2.6s ease-in-out infinite;
		}
	}
</style>
